<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 列出会话</span></span>
